// The range basket at runtime: every range's scores are in ranges/index.js
// (generated by tools/build-ranges.mjs); each range's skyline profile is
// its own module, loaded only when a song is matched to it. That split is
// what lets the basket grow to hundreds of ranges without the page
// downloading all of them.
//
// A song gets three ranges, one per ridge: a high one at the back, a mid
// one in the middle and a low one in front (BiomeSet.chooseBiomeRidges).
// Each range's module holds the skyline scanned for its far layer; that one
// skyline is what the song's ridge draws, whichever ridge it stands on.
import { RANGES, LOADERS } from './ranges/index.js';
import { RIDGE_BANDS } from './RangeMatcher.js';
import { readRecentRanges, readRecentViews, readRecentRegions } from './RangeHistory.js';
import { assignSongScenes } from './SceneCatalog.js';
import SCENE_CATALOG from './sceneCatalogData.js';
import { chooseSongBiomes, chooseBiomeRidges } from './BiomeSet.js';
import { profilesFromJSON } from './TerrainProfile.js';
import { REAL_BIOME_NAMES } from '../RealBiomes.js';
import { chooseHorizonRange, MASSIF_SALT } from './HorizonRidge.js';

export { RANGES };

/** Load a range's baked skyline and turn it into terrain profiles. Rejects
 *  on an unknown id or a profile TerrainProfile will not accept. */
export async function loadRangeProfiles(id) {
  const load = LOADERS[id];
  if (!load) throw new Error(`no range '${id}' in the basket`);
  const mod = await load();
  return profilesFromJSON(mod.default);
}

/**
 * The song's biomes and the ranges standing in each (BiomeSet.js). Resolves
 * as soon as the home biome -- the one the song opens in -- has loaded, to
 *   { biomes, home, byBiome, whenAll, allLoaded, range, ranges, profiles, horizon, massif }
 * where `byBiome` maps a biome name to { ranges: { far, mid, near },
 * profiles: { L2, L3, L4 } } and fills in as the others load (`whenAll`
 * settles when they have), and `range`/`ranges`/`profiles` are the home
 * biome's. A biome whose back range fails to load is left out of byBiome,
 * and its sections draw the game's own hills. Resolves to null -- never
 * rejects -- when the home biome cannot load: the song falls back to the
 * bundled Tetons. `horizon` is { range, profile }, the famous skyline the
 * horizon EQ dances on (HorizonRidge.js), loaded alongside the home biome;
 * null when it failed, and the EQ keeps its own shape. `massif` is the same
 * for the spectrum massif behind it: another of those skylines, never the
 * horizon's. `sceneByBiome` maps each biome to its Range v2 SceneChoice
 * ({ view, fallbackReason }) from the curated catalog, drawn once per song.
 * `biome` (the player's pick, ui/SceneChoice.js) keeps the whole song in
 * that one biome instead of drawing the song's own; an unknown name is
 * ignored.
 */
export async function prepareSongTerrain(profile, seed, recent = readRecentRanges(), { biome: pinned = null } = {}) {
  try {
    const biomes = pinned && REAL_BIOME_NAMES.includes(pinned) ? [pinned] : chooseSongBiomes(profile, seed);
    if (!biomes.length) return null;
    const byBiome = new Map();
    const load = async (biome) => {
      const set = chooseBiomeRidges(biome, profile, seed, { recent });
      const loaded = await Promise.all(RIDGE_BANDS.map(async (b) => {
        const match = set[b.ridge];
        if (!match) return null;
        try {
          const layers = await loadRangeProfiles(match.range.id);
          return layers.L2 ? { ridge: b.ridge, layer: b.layer, range: match.range, skyline: layers.L2 } : null;
        } catch (err) {
          if (b.ridge === 'far') throw err;
          console.warn(`[terrain] ${biome} ${b.ridge} range unavailable; that ridge stays invented`, err);
          return null;
        }
      }));
      if (!loaded.some((x) => x?.ridge === 'far')) return null;
      const entry = { biome, ranges: {}, profiles: {} };
      for (const x of loaded) {
        if (!x) continue;
        entry.ranges[x.ridge] = x.range;
        entry.profiles[x.layer] = x.skyline;
      }
      byBiome.set(biome, entry);
      return entry;
    };
    const homeIds = Object.values(chooseBiomeRidges(biomes[0], profile, seed, { recent }))
      .map((m) => m?.range?.id).filter(Boolean);
    const loadSkyline = async (range, what) => {
      if (!range) return null;
      try {
        const layers = await loadRangeProfiles(range.id);
        return layers.L2 ? { range, profile: layers.L2 } : null;
      } catch (err) {
        console.warn(`[terrain] ${what} range unavailable; it keeps its own shape`, err);
        return null;
      }
    };
    const horizonRange = chooseHorizonRange(seed, { exclude: homeIds });
    const massifRange = chooseHorizonRange(seed, {
      exclude: [...homeIds, horizonRange?.id].filter(Boolean), salt: MASSIF_SALT,
    });
    const [home, horizon, massif] = await Promise.all([
      load(biomes[0]), loadSkyline(horizonRange, 'horizon'), loadSkyline(massifRange, 'massif'),
    ]);
    if (!home) return null;
    const whenAll = Promise.all(biomes.slice(1).map((b) => load(b).catch((err) => {
      console.warn(`[terrain] ${b} unavailable; its sections stay invented`, err);
      return null;
    })));
    // Range v2: one lightweight scenic assignment per biome, drawn once for
    // this song. Not a GPU preparation; RangePresentation loads the active
    // and next view on demand. A biome without an approved view carries a
    // null view and a fallback reason; its sections keep the legacy ranges.
    let sceneByBiome = new Map();
    try {
      sceneByBiome = assignSongScenes(biomes, profile, seed, SCENE_CATALOG,
        { recentViewIds: readRecentViews(), recentRegionIds: readRecentRegions() });
    } catch (err) {
      console.warn('[terrain] scenic catalog unavailable; legacy ranges only', err);
    }
    const terrain = {
      biomes, home: biomes[0], byBiome, whenAll, allLoaded: false,
      range: home.ranges.far, ranges: home.ranges, profiles: home.profiles, horizon, massif,
      sceneByBiome, catalogVersion: SCENE_CATALOG.catalogVersion,
    };
    whenAll.then(() => { terrain.allLoaded = true; });
    return terrain;
  } catch (err) {
    console.warn('[terrain] song biomes unavailable; using the bundled Tetons', err);
    return null;
  }
}
